const flower=(x,y,s,c='#f7ada1')=>`<g transform="translate(${x} ${y}) scale(${s})">${[0,60,120,180,240,300].map(r=>oval(0,-12,9,14,c,`transform="rotate(${r})"`)).join('')}${circle(0,0,8,'#ffe49b')}</g>`;
const flame=(x,y,s,c='#ff9d68')=>`<g transform="translate(${x} ${y}) scale(${s})">${path('M0 0Q-23-11-13-34Q-12-19-3-24Q8-34 5-52Q32-22 15-4Z',c)}${path('M0-3Q-8-12 2-27Q16-11 7-3Z','#ffe5a0')}</g>`;
