const shell=(x,y,s,c='#e7bea2')=>`<g transform="translate(${x} ${y}) scale(${s})">${path('M-22 5Q-30-24-13-29L0-24 12-29Q32-19 22 5L0 15Z',c)}${line('M0 11V-20M-3 11L-15-20M3 11L16-20',INK,2)}</g>`;
