const arm=(side,x)=>`<g class="arm-${side}">${line(`M${side==='l'?128-bw:112+bw} ${sy}Q${x} ${sy+8} ${x} ${ay}`,INK,hand*1.7+7)}${line(`M${side==='l'?128-bw:112+bw} ${sy}Q${x} ${sy+8} ${x} ${ay}`,c.fur,hand*1.7)}${circle(x,ay,hand,c.fur,`stroke="${INK}" stroke-width="3"`)}<g transform="translate(${x} ${ay})" stroke="${INK}" stroke-width="2.3">${parts.hand||''}</g></g>`;
