// Single configurable location for optional externally hosted asset packages.
// The local inline rigs always provide a complete, dependable first render.
export function assetBase(){return String(globalThis.MONKEY_TRAILS_ASSET_BASE||new URL('./assets/',import.meta.url).href).replace(/\/?$/,'/');}
export function assetUrl(relative){return assetBase()+String(relative).replace(/^\//,'');}
// Upgrade mounted portraits only after an optional hosted image has loaded.
// A broken CDN tries the committed local file; two failures leave the animated
// inline rig in place. Evolved combat poses remain modular inline SVG scenes.
export function hydrateHostedPortraits(root,{reducedMotion=false}={}){
 const view=root?.ownerDocument?.defaultView||globalThis.window;
 if(!globalThis.MONKEY_TRAILS_ASSET_BASE||!root?.querySelectorAll||!view?.Image)return;
 if(reducedMotion||view.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;
 for(const svg of root.querySelectorAll('svg.monkey-art[data-species]')){
  if(svg.dataset.hostedRequested||svg.dataset.reduced==='true'||svg.closest('.reduced-motion,.reduce-motion,.battery-saving,.battery-saver'))continue;
  const entry=ASSET_MANIFEST.species[svg.dataset.species],stage=Number(svg.dataset.stage)||0,state=svg.dataset.state||'idle';
  const species=SPECIES[svg.dataset.species],packagedTypes=stage>0?(species?.types.length?species.types:['leaf']):species?.types;
  if(svg.dataset.types!==JSON.stringify(packagedTypes))continue;
  const variant=['base','attuned','elder','ascendant'][stage];
  const src=stage===0?entry?.states[state]?.src:state==='idle'&&variant?`monkeys/${svg.dataset.species}/variants/${variant}.svg`:null;
  if(!src)continue;
  svg.dataset.hostedRequested='true';
  const img=new view.Image();let local=false;
  img.className=svg.getAttribute('class');img.alt=svg.getAttribute('aria-label')||'';
  for(const [key,value] of Object.entries(svg.dataset))img.dataset[key]=value;
  img.width=240;img.height=240;img.decoding='async';
  img.addEventListener('load',()=>{if(svg.isConnected&&!svg.closest('.reduced-motion,.reduce-motion,.battery-saving,.battery-saver')&&!view.matchMedia?.('(prefers-reduced-motion: reduce)').matches)svg.replaceWith(img);},{once:true});
  img.addEventListener('error',()=>{if(!local){local=true;img.src=new URL(`./assets/${src}`,import.meta.url).href;}});
  img.src=assetUrl(src);
 }
}
export const ASSET_MANIFEST={version:3,format:'animated-svg',base:'./assets/',viewBox:[0,0,240,240],placeholder:'interface/loading.svg',animations:Object.fromEntries([...ANIMATION_STATES,...ULTRA_STATES].map(state=>[state,{frames:1,render:'css-vector-rig',durationMs:({idle:3000,walk:550,attack:650,cast:1200,hit:500,knockout:700,victory:1200,arrival:2000,signature:1800})[state],loop:!['knockout','arrival'].includes(state)}])),species:Object.fromEntries(Object.values(SPECIES).map(s=>[s.id,{number:s.number,scale:s.rarity==='ultra'?1.08:1,anchor:[.5,.90],portrait:`monkeys/${s.id}/idle.svg`,states:Object.fromEntries([...ANIMATION_STATES,...(s.rarity==='ultra'?ULTRA_STATES:[])].map(state=>[state,{src:`monkeys/${s.id}/${state}.svg`,frames:[0],anchor:[.5,.90]}])),variants:{base:{stage:0},attuned:{stage:1,modular:true},elder:{stage:2,modular:true},ascendant:{stage:3,modular:true}}}])),environments:Object.fromEntries(Object.keys(ELEMENTS).map(t=>[t,`environments/${t}.svg`])),pickups:Object.fromEntries([...Object.keys(ITEMS),...Object.keys(GEAR),'fruit','fragment','camp','marker','ultraMarker'].map(id=>[id,`interface/${id}.svg`]))};
